import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.BQh0MzVE.js";var i=JSON.parse(`{"title":"Secrets","description":"","frontmatter":{},"headers":[],"relativePath":"pages/config/secrets.md","filePath":"pages/config/secrets.md"}`),a={name:`pages/config/secrets.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to “Secrets”">​</a></h1><p>Secret references are supported for both single-target and multi-target (jobs) setups, so you can use them in both cases without any issues. Just make sure to use the correct syntax and provide the necessary parameters for the secret manager you choose. Also check the permissions and access policies for the secret manager to ensure that SQL Exporter has the necessary access to read the secrets.</p><p>Secrets are <strong>only</strong> resolved at startup, so if the secret value changes, you may need to restart SQL Exporter to pick up the new value. Or use the <code>/reload</code> endpoint to trigger a configuration reload without restarting the process, but keep in mind that this will also reload the entire configuration, not just the secrets.</p><p>SQL Exporter supports multiple secret management backends:</p><ul><li>Kubernetes Secrets</li><li>AWS Secrets Manager</li><li>Google Cloud Secret Manager</li><li>Hashicorp Vault</li></ul><h2 id="kubernetes-secrets" tabindex="-1"><strong>Kubernetes Secrets</strong>: <a class="header-anchor" href="#kubernetes-secrets" aria-label="Permalink to “Kubernetes Secrets:”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>k8ssecret://[namespace/]secret-name?key=field&amp;template=dsn_template</span></span></code></pre></div><p>Recommended for Kubernetes deployments. Requires RBAC permissions for the service account to read secrets. See <a href="https://github.com/burningalchemist/sql_exporter/examples/k8s-secret/" target="_blank" rel="noreferrer">k8s-secret example</a> for detailed setup instructions and the Helm chart automatically creates necessary RBAC resources.</p><h2 id="aws-gcp-secret-manager" tabindex="-1"><strong>AWS/GCP Secret Manager</strong>: <a class="header-anchor" href="#aws-gcp-secret-manager" aria-label="Permalink to “AWS/GCP Secret Manager:”">​</a></h2><p>If the database runs on AWS or Google Cloud, you might want to store the DSN in their Secret Manager services and allow SQL Exporter to access it from there. This way you can avoid hardcoding credentials in the configuration file and benefit from the security features of these services. In addition, Vault is also available as a secret manager option for SQL Exporter.</p><p>The secrets can be referenced in the configuration file as a value for <code>data_source_name</code> item using the following syntax:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awssecretsmanager://&lt;SECRET_NAME&gt;?region=&lt;AWS_REGION&gt;&amp;key=&lt;JSON_KEY&gt;</span></span>
<span class="line"><span>gcpsecretsmanager://&lt;SECRET_NAME&gt;?project_id=&lt;GCP_PROJECT_ID&gt;&amp;key=&lt;JSON_KEY&gt;</span></span></code></pre></div><p>The secret value can be a simple string or a JSON object:</p><ul><li>If it&#39;s a JSON object, you need to specify the <code>key</code> query parameter to indicate which value to use as the DSN;</li><li>If the secret is a valid JSON but the <code>key</code> is not specified, SQL Exporter will try to use the value of <code>data_source_name</code> key by default;</li><li>If it&#39;s a simple string, then it will be used as a connection string directly.</li></ul><p>Using JSON format gives more flexibility and allows to store additional information or multiple DSNs in the same secret resource.</p><h2 id="hashicorp-vault" tabindex="-1"><strong>Hashicorp Vault</strong> <a class="header-anchor" href="#hashicorp-vault" aria-label="Permalink to “Hashicorp Vault”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hashivault://&lt;MOUNT&gt;/&lt;SECRET_PATH&gt;?key=&lt;JSON_KEY&gt;</span></span></code></pre></div><p>For Vault, you also need to specify the <code>VAULT_ADDR</code> and <code>VAULT_TOKEN</code> environment variables to let SQL Exporter authenticate. This is a regular practice and goes beyond the scope of this document, so please refer to Vault documentation for more details on how to set up and use Vault for secrets management.</p>`,18)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};